//! Database seeder binary for module: employee
//!
//! Generated by metaphor-schema. Do not edit manually.
//!
//! Run with: cargo run --bin employee-seeder
//! Or via CLI: backbone seed run --module employee
//!
//! This binary runs all registered seeders in order.

use anyhow::Result;
use sqlx::postgres::PgPoolOptions;
use std::env;

// Import seeders
use backbone_employee::seeders::SeedBankSeeder;
use backbone_employee::seeders::SeedDataConsentSeeder;
use backbone_employee::seeders::SeedDataSubjectRequestSeeder;
use backbone_employee::seeders::SeedEmployeeSeeder;
use backbone_employee::seeders::SeedEmployeeBankAccountSeeder;
use backbone_employee::seeders::SeedEmployeeBpjsSeeder;
use backbone_employee::seeders::SeedEmployeeCertificationSeeder;
use backbone_employee::seeders::SeedEmployeeContactSeeder;
use backbone_employee::seeders::SeedEmployeeEducationSeeder;
use backbone_employee::seeders::SeedEmployeeFamilySeeder;
use backbone_employee::seeders::SeedEmployeeIdentitySeeder;
use backbone_employee::seeders::SeedEmployeeTaxSeeder;
use backbone_employee::seeders::SeedEmployeeWorkExperienceSeeder;
use backbone_employee::seeders::SeedEmploymentSeeder;
use backbone_employee::seeders::SeedEmploymentHistorySeeder;
use backbone_employee::seeders::SeedPiiAccessLogSeeder;
use backbone_employee::seeders::SeedReligionSeeder;
use backbone_employee::seeders::Seeder;

#[tokio::main]
async fn main() -> Result<()> {
    let args: Vec<String> = env::args().collect();
    let force = args.iter().any(|a| a == "--force");
    let filter: Option<&str> = args.iter()
        .skip(1)
        .find(|a| !a.starts_with("-"))
        .map(|s| s.as_str());

    let database_url = env::var("DATABASE_URL")
        .expect("DATABASE_URL must be set");

    println!("Connecting to database...");

    let pool = PgPoolOptions::new()
        .max_connections(5)
        .connect(&database_url)
        .await?;

    println!("Connected to database");
    println!();
    println!("Running seeders for module: employee");
    println!();

    // Register seeders in order
    let mut seeders: Vec<Box<dyn Seeder + Send + Sync>> = Vec::new();
    seeders.push(Box::new(SeedBankSeeder::new()));
    seeders.push(Box::new(SeedDataConsentSeeder::new()));
    seeders.push(Box::new(SeedDataSubjectRequestSeeder::new()));
    seeders.push(Box::new(SeedEmployeeSeeder::new()));
    seeders.push(Box::new(SeedEmployeeBankAccountSeeder::new()));
    seeders.push(Box::new(SeedEmployeeBpjsSeeder::new()));
    seeders.push(Box::new(SeedEmployeeCertificationSeeder::new()));
    seeders.push(Box::new(SeedEmployeeContactSeeder::new()));
    seeders.push(Box::new(SeedEmployeeEducationSeeder::new()));
    seeders.push(Box::new(SeedEmployeeFamilySeeder::new()));
    seeders.push(Box::new(SeedEmployeeIdentitySeeder::new()));
    seeders.push(Box::new(SeedEmployeeTaxSeeder::new()));
    seeders.push(Box::new(SeedEmployeeWorkExperienceSeeder::new()));
    seeders.push(Box::new(SeedEmploymentSeeder::new()));
    seeders.push(Box::new(SeedEmploymentHistorySeeder::new()));
    seeders.push(Box::new(SeedPiiAccessLogSeeder::new()));
    seeders.push(Box::new(SeedReligionSeeder::new()));

    // Sort by order
    seeders.sort_by_key(|s| s.order());

    // Run seeders
    for seeder in &seeders {
        let name = seeder.name();

        // Apply filter if specified
        if let Some(f) = filter {
            if !name.contains(f) {
                continue;
            }
        }

        if force {
            println!("   Running {}...", name);
            seeder.run(&pool).await?;
            println!("   {} completed", name);
        } else {
            println!("   Checking {}...", name);
            if seeder.should_run(&pool).await? {
                println!("   Running {}...", name);
                seeder.run(&pool).await?;
                println!("   {} completed", name);
            } else {
                println!("   {} already applied, skipping", name);
            }
        }
    }

    println!();
    println!("All seeders completed successfully!");

    Ok(())
}
